SELECT 'gongkao', '父子母女基础', 'kp-age-b-family', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "父子母女基础关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心常识：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "父母与子女的年龄差通常在 20~35 岁之间。这在盲猜选项时极其重要。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "以家庭为背景的年龄题，除了算术逻辑，还附带了隐藏的生物学逻辑。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算出反人类结果：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果你算出父亲 20 岁，儿子 15 岁；或者母亲 50 岁，女儿 40 岁。请立刻停笔，你一定是加减号列反了！在代入排除法时，直接划掉那些不符合人类生育常识的选项组合。"}]}]}]}$$ AS jsonb), NULL, '父子母女基础的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "父子母女基础"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_b_family", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
